(window.VADE_TASKS=window.VADE_TASKS||{})["FIN2-019"]={"id": "FIN2-019", "number": 19, "domain": "finance", "released": true, "group": "Fabless Semiconductors", "category": "Earnings Analysis", "title": "Qualcomm: explaining the change in QCT margins", "question": "Qualcomm's QCT segment EBT margin was lower year over year in both fiscal Q2 2026 (three months ended March 29, 2026) and fiscal Q3 2026 (three months ended June 28, 2026). Using Qualcomm's Form 10-Q filings for those two quarters and its fiscal Q3 2026 earnings release (information available through July 29, 2026), determine what is driving this compression and how management's own attribution compares with the segment line items. Measure the product-cost component as the change in QCT cost of revenues as a percentage of QCT revenues, and the operating-expense component as the change in QCT research and development plus selling, general and administrative expenses as a percentage of QCT revenues, both in percentage points. Make the comparison for each of fiscal Q2 2026 and fiscal Q3 2026 against the same quarter of the prior year, and for fiscal Q3 2026 against fiscal Q2 2026 sequentially, and identify which component is larger in each comparison. For each of the fiscal Q2 2026 and fiscal Q3 2026 three-month periods separately, judge whether management's stated attribution of the QCT EBT-margin change is complete, meaning it names every QCT line item whose ratio to QCT revenues moved adversely year over year, or incomplete because it omits any such item; identify any omitted item and which of the named items match the segment line items, using the three-month attributions rather than the first-nine-months attribution. State how these segment measures differ from Qualcomm's consolidated gross margin. Report Qualcomm's own inventory balances (not OEM channel inventory) at September 28, 2025, March 29, 2026 and June 28, 2026 in USD millions, with the change over that period in USD millions and in percent to one decimal. Describe how the outlook description of product-cost drivers, and of the related supply risk to revenue, changed between the fiscal Q2 2026 and fiscal Q3 2026 10-Qs. Finally, judge whether QCT margin recovery can be modelled as reversing with OEM inventory normalisation, weighing that outlook change, the inventory trend, management's pricing actions, and fiscal Q4 2026 QCT revenue guidance. Compute ratios from the USD million line items and state ratio changes to two decimals.", "cutoff": "2026-07-29", "core_conclusion": "QCT segment EBT-margin compression is opex-led in Q2 FY26 YoY (opex ratio +2.28 pp vs cost ratio +0.73 pp) and cost-led in Q3 FY26 YoY (cost ratio +2.35 pp vs opex ratio +1.58 pp; computed -3.92 pp vs reported -4 points), with both ratios worsening sequentially and opex narrowly larger (+0.82 vs +0.57 pp) as revenue fell $572M while opex fell only $51M. Management's Q2 FY26 attribution list is consistent with the line items (higher operating expenses, lower gross margin, lower revenues); the Q3 FY26 list is only partially consistent: its two items (lower gross margin, lower revenues) match, but it omits the operating-expense item although the segment opex ratio rose +1.58 pp YoY. The nine-month list is not scored. Between the Q2 and Q3 10-Q outlooks the product-cost driver shifts from leading-node wafer-supplier cost to a broad-based industry input-cost and capacity increase (in part AI/data-center demand), with a new lost-or-delayed-revenue supply risk. Management's remedy is pricing actions that benefit gross margins only gradually, so the gross-margin component cannot be modelled as reversing with OEM inventory normalisation alone. Qualcomm's inventory rose $1,853M to $8,379M and Q4 FY26 QCT guidance of $8.4B-$9.0B brackets the Q3 level, so the evidence does not support a near-term volume rebound beyond management's stated outlook.", "atoms": [{"label": "QCT segment cost-of-revenues-to-revenue ratio change, three months ended June 28, 2026 vs three months ended June 29, 2025 (computed, percentage points)", "expected": "Computed +2.35 percentage points (52.35% vs 50.01%; 4,452/8,504 vs 4,497/8,993; two-decimal half-up rounding of exact quotients)", "unit": "percentage points", "tolerance": 0.05, "fatal": true, "scored": true, "evidence": [1, 2]}, {"label": "QCT segment R&D plus SG&A operating-expense-to-revenue ratio change, Q3 FY26 vs Q3 FY25 (computed, percentage points)", "expected": "Computed +1.58 percentage points (21.87% vs 20.29%; 1,860/8,504 vs 1,825/8,993); together with the cost-ratio change this gives a computed EBT-margin change of -3.92 pp (25.78% vs 29.70%), consistent with the reported -4 points (whole-point rounding)", "unit": "percentage points", "tolerance": 0.05, "fatal": true, "scored": true, "evidence": [1, 3, 4, 8]}, {"label": "QCT segment cost-of-revenues-to-revenue ratio change, three months ended March 29, 2026 vs three months ended March 30, 2025 (computed, percentage points)", "expected": "Computed +0.73 percentage points (51.78% vs 51.05%; 4,700/9,076 vs 4,834/9,469)", "unit": "percentage points", "tolerance": 0.05, "fatal": true, "scored": true, "evidence": [32, 33]}, {"label": "QCT segment R&D plus SG&A operating-expense-to-revenue ratio change, Q2 FY26 vs Q2 FY25 (computed, percentage points)", "expected": "Computed +2.28 percentage points (21.06% vs 18.78%; 1,911/9,076 vs 1,778/9,469); together with the cost-ratio change this gives a computed EBT-margin change of -3.01 pp (27.16% vs 30.17%), consistent with the reported -3 points (whole-point rounding)", "unit": "percentage points", "tolerance": 0.05, "fatal": true, "scored": true, "evidence": [32, 34, 35, 36]}, {"label": "QCT segment cost-of-revenues-to-revenue ratio change, Q3 FY26 vs Q2 FY26 sequential (computed, percentage points)", "expected": "Computed +0.57 percentage points (52.35% vs 51.78%)", "unit": "percentage points", "tolerance": 0.05, "fatal": true, "scored": true, "evidence": [1, 2, 32, 33]}, {"label": "QCT segment operating-expense-to-revenue ratio change Q3 FY26 vs Q2 FY26 sequential (computed, percentage points), with sequential dollar changes in QCT revenue and QCT operating expenses", "expected": "Computed +0.82 percentage points (21.87% vs 21.06%); QCT revenue -$572M (-6.3%, 8,504 vs 9,076) while R&D+SG&A fell only -$51M (-2.7%, 1,860 vs 1,911); computed sequential EBT-margin change -1.38 pp", "unit": "percentage points", "tolerance": 0.05, "fatal": true, "scored": true, "evidence": [1, 3, 32, 34]}, {"label": "Larger contributor to QCT EBT-margin compression for Q3 FY26 YoY, Q2 FY26 YoY and Q3 vs Q2 FY26 sequential, each chosen from {cost-of-revenues ratio, R&D+SG&A operating-expense ratio}", "expected": "Q3 YoY: cost-of-revenues ratio larger (+2.35 vs +1.58 pp); Q2 YoY: operating-expense ratio larger (+2.28 vs +0.73 pp); sequential Q2-to-Q3: operating-expense ratio narrowly larger (+0.82 vs +0.57 pp), both ratios worsened", "unit": null, "tolerance": null, "fatal": true, "scored": true, "evidence": [1, 2, 3, 32, 33, 34]}, {"label": "Per-period agreement between management's QCT EBT-margin attribution lists and the computed segment line-item ratio changes, labelled separately for Q2 FY26 (three months ended March 29, 2026) and Q3 FY26 (three months ended June 28, 2026), including whether the operating-expense item is listed; the first-nine-months list is not scored", "expected": "Q2 FY26: consistent. The list names higher operating expenses (first), lower gross margin and lower revenues; the segment line items show the opex ratio up +2.28 pp (opex $1,911M vs $1,778M), the cost ratio up +0.73 pp and revenues lower ($9,076M vs $9,469M), so every listed item matches and the opex item, the larger computed change, is included. Q3 FY26: partially consistent (incomplete). The list names only lower gross margin and lower revenues, which match the cost ratio up +2.35 pp (the larger YoY change) and revenues lower ($8,504M vs $8,993M), but it omits the operating-expense item although segment opex rose to $1,860M from $1,825M on lower revenue and the opex ratio rose +1.58 pp. First nine months: not scored; the nine-month list (which names higher operating expenses first) is context only because no nine-month segment line items are bound in this reference analysis.", "unit": null, "tolerance": null, "fatal": true, "scored": true, "evidence": [1, 2, 3, 9, 10, 11, 32, 33, 34, 37, 38]}, {"label": "Scope of the QCT segment cost-of-revenues ratio relative to consolidated gross margin (unallocated cost of revenues and unallocated R&D/SG&A inside or outside segment EBT)", "expected": "Segment EBT margin is not consolidated gross margin: unallocated cost of revenues ($97M vs $65M in the three-month periods), unallocated R&D ($755M vs $595M) and unallocated SG&A ($323M vs $182M) are reconciling items excluded from QCT segment EBT", "unit": null, "tolerance": null, "fatal": true, "scored": true, "evidence": [4, 5, 6, 7]}, {"label": "QCT automotive revenue increase split into revenues-per-unit and higher-shipments amounts for Q2 FY26 and Q3 FY26 (each vs prior-year quarter), with the computed per-unit share of the Q3 increase", "expected": "Reported: Q2 $176M per-unit vs $191M shipments; Q3 $381M per-unit vs $223M shipments (Q3 automotive increase $604M). Computed per-unit share of the Q3 increase about 63.1% (381/604, one-decimal rounding). Per-unit gains reflect favorable mix and higher ASPs; they are evidence of an ASP offset, not proof of a margin offset.", "unit": "percent", "tolerance": 0.5, "fatal": false, "scored": false, "evidence": [15, 16, 17, 18, 39, 40]}, {"label": "Qualcomm total inventories at September 28, 2025, March 29, 2026 and June 28, 2026, and the total increase from September 28, 2025 to June 28, 2026", "expected": "Reported $6,526M -> $7,368M -> $8,379M; computed increase $1,853M (+28.4%, one-decimal rounding), with the March-to-June quarter step (+$1,011M) larger than the step to March 29, 2026 (+$842M, two quarters); the 10-Q cash-flow discussion ties the inventory increase to customer demand impacts from memory supply constraints. This is Qualcomm's own inventory, not OEM channel inventory.", "unit": "USD millions", "tolerance": 0, "fatal": true, "scored": true, "evidence": [19, 20, 21, 22, 23, 41, 42, 43]}, {"label": "Product-cost driver named in the next-several-quarters outlook of the Q2 FY26 10-Q versus the Q3 FY26 10-Q, and whether a supply-constraint lost-or-delayed-revenue risk appears in the Q3 FY26 outlook", "expected": "Q2 FY26 10-Q outlook: leading process technology nodes expected to continue to drive product cost increases from certain key semiconductor wafer suppliers. Q3 FY26 10-Q outlook: a broad-based industry increase in input costs and capacity constraints across wafer fabrication, assembly, test, advanced packaging, memory and other materials, due in part to demand for leading-edge technologies, AI and data center applications, with continued product-cost increases from certain key suppliers that could negatively impact margins. The Q3 outlook adds that supply and capacity constraints could leave customer demand unmet, resulting in lost or delayed revenue. The Q3 earnings release repeats the broad-based input-cost wording and ties pricing actions to the higher input costs. Scope: this change is within the outlook section; it is not a statement that node-driven cost has ceased.", "unit": null, "tolerance": null, "fatal": true, "scored": true, "evidence": [25, 26, 27, 28, 29, 30, 31, 44, 45, 46, 49, 50, 55]}, {"label": "Source-bounded judgment on QCT margin recovery: dominant Q3 FY26 compression component, whether the gross-margin component can be modelled as reversing with OEM inventory normalisation, and what inventory, supply risk, pricing actions and Q4 FY26 QCT guidance imply", "expected": "In Q3 FY26 the cost-of-revenues (gross-margin) component is the larger YoY driver (+2.35 vs +1.58 pp), though the opex ratio remains material and is narrowly larger sequentially. Management ties higher product cost to a broad-based industry increase in input costs, due in part to AI and data center demand, and names pricing actions that benefit gross margins only over time as pricing changes gradually come into effect; on this evidence the gross-margin component cannot be modelled as reversing with OEM inventory normalisation alone. The handset decline (lower shipments as OEMs reduce inventory amid memory supply constraints) is the volume path behind the opex deleverage (sequential revenue -$572M vs opex -$51M). Qualcomm's rising inventory ($8,379M), the continued expectation that memory constraints will adversely affect demand from several handset OEMs, the new lost-or-delayed-revenue supply risk, and Q4 FY26 QCT guidance of $8.4B-$9.0B (bracketing Q3 QCT revenue of $8,504M) do not support a near-term volume rebound beyond management's stated outlook. Limits: no QCT-specific gross margin, price pass-through magnitude, OEM-specific amounts or OEM channel inventory are disclosed.", "unit": null, "tolerance": null, "fatal": true, "scored": true, "evidence": [1, 2, 3, 12, 13, 14, 21, 24, 25, 27, 30, 31, 32, 34, 48, 50, 51, 52, 53, 54]}], "requirements": [{"atom": "QCT segment cost-of-revenues-to-revenue ratio change, three months ended June 28, 2026 vs three months ended June 29, 2025 (computed, percentage points)", "criterion": "States the QCT cost-of-revenues-to-revenue ratio change for fiscal Q3 2026 vs fiscal Q3 2025 as about +2.35 percentage points (52.35% vs 50.01%; 4,452/8,504 vs 4,497/8,993), within +/-0.05 pp, computed from USD million line items.", "fatal": true}, {"atom": "QCT segment R&D plus SG&A operating-expense-to-revenue ratio change, Q3 FY26 vs Q3 FY25 (computed, percentage points)", "criterion": "States the QCT R&D plus SG&A ratio change for fiscal Q3 2026 vs fiscal Q3 2025 as about +1.58 percentage points (21.87% vs 20.29%; 1,860/8,504 vs 1,825/8,993), within +/-0.05 pp; a computed EBT-margin change of about -3.92 pp versus the reported -4 points is acceptable as whole-point rounding.", "fatal": true}, {"atom": "QCT segment cost-of-revenues-to-revenue ratio change, three months ended March 29, 2026 vs three months ended March 30, 2025 (computed, percentage points)", "criterion": "States the QCT cost-of-revenues-to-revenue ratio change for fiscal Q2 2026 vs fiscal Q2 2025 as about +0.73 percentage points (51.78% vs 51.05%; 4,700/9,076 vs 4,834/9,469), within +/-0.05 pp.", "fatal": true}, {"atom": "QCT segment R&D plus SG&A operating-expense-to-revenue ratio change, Q2 FY26 vs Q2 FY25 (computed, percentage points)", "criterion": "States the QCT R&D plus SG&A ratio change for fiscal Q2 2026 vs fiscal Q2 2025 as about +2.28 percentage points (21.06% vs 18.78%; 1,911/9,076 vs 1,778/9,469), within +/-0.05 pp; a computed EBT-margin change of about -3.01 pp versus the reported -3 points is acceptable.", "fatal": true}, {"atom": "QCT segment cost-of-revenues-to-revenue ratio change, Q3 FY26 vs Q2 FY26 sequential (computed, percentage points)", "criterion": "States the sequential (fiscal Q3 2026 vs fiscal Q2 2026) QCT cost-of-revenues ratio change as about +0.57 percentage points (52.35% vs 51.78%), within +/-0.05 pp.", "fatal": true}, {"atom": "QCT segment operating-expense-to-revenue ratio change Q3 FY26 vs Q2 FY26 sequential (computed, percentage points), with sequential dollar changes in QCT revenue and QCT operating expenses", "criterion": "States the sequential QCT R&D plus SG&A ratio change as about +0.82 percentage points (21.87% vs 21.06%), within +/-0.05 pp. Supporting context: QCT revenue fell about $572M while R&D+SG&A fell only about $51M.", "fatal": true}, {"atom": "Larger contributor to QCT EBT-margin compression for Q3 FY26 YoY, Q2 FY26 YoY and Q3 vs Q2 FY26 sequential, each chosen from {cost-of-revenues ratio, R&D+SG&A operating-expense ratio}", "criterion": "Identifies the larger component in each comparison: fiscal Q3 2026 YoY cost-of-revenues ratio larger (+2.35 vs +1.58 pp); fiscal Q2 2026 YoY operating-expense ratio larger (+2.28 vs +0.73 pp); sequential Q2-to-Q3 operating-expense ratio narrowly larger (+0.82 vs +0.57 pp), with both ratios worsening.", "fatal": true}, {"atom": "Per-period agreement between management's QCT EBT-margin attribution lists and the computed segment line-item ratio changes, labelled separately for Q2 FY26 (three months ended March 29, 2026) and Q3 FY26 (three months ended June 28, 2026), including whether the operating-expense item is listed; the first-nine-months list is not scored", "criterion": "Fiscal Q2 2026: judges management's attribution complete (consistent): it names higher operating expenses, lower gross margin and lower revenues, all of which match the segment line items (opex ratio +2.28 pp, cost ratio +0.73 pp, revenues $9,076M vs $9,469M). Fiscal Q3 2026: judges it incomplete: its named items (lower gross margin, lower revenues) match the line items (cost ratio +2.35 pp, revenues $8,504M vs $8,993M), but it omits the operating-expense item although the opex ratio rose about +1.58 pp (opex $1,860M vs $1,825M on lower revenue). The nine-month list is not scored.", "fatal": true}, {"atom": "Scope of the QCT segment cost-of-revenues ratio relative to consolidated gross margin (unallocated cost of revenues and unallocated R&D/SG&A inside or outside segment EBT)", "criterion": "States that QCT segment measures are not consolidated gross margin: unallocated cost of revenues, unallocated R&D and unallocated SG&A are reconciling items excluded from QCT segment EBT (for example unallocated cost of revenues $97M vs $65M, R&D $755M vs $595M, SG&A $323M vs $182M in the three-month periods); exact amounts are supporting, the exclusion is required.", "fatal": true}, {"atom": "Qualcomm total inventories at September 28, 2025, March 29, 2026 and June 28, 2026, and the total increase from September 28, 2025 to June 28, 2026", "criterion": "Reports Qualcomm's own inventories of $6,526M (Sept 28, 2025), $7,368M (Mar 29, 2026) and $8,379M (Jun 28, 2026), with an increase of $1,853M and about +28.4% (one-decimal rounding; +/-0.1 pp acceptable), identified as Qualcomm's inventory rather than OEM channel inventory.", "fatal": true}, {"atom": "Product-cost driver named in the next-several-quarters outlook of the Q2 FY26 10-Q versus the Q3 FY26 10-Q, and whether a supply-constraint lost-or-delayed-revenue risk appears in the Q3 FY26 outlook", "criterion": "Describes the outlook change: the fiscal Q2 2026 10-Q attributes product cost increases to leading process technology nodes at certain key wafer suppliers; the fiscal Q3 2026 10-Q describes a broad-based industry increase in input costs and capacity constraints (wafer fabrication, assembly, test, advanced packaging, memory, other materials), due in part to AI and data center demand, and adds a new risk that supply and capacity constraints could leave demand unmet, resulting in lost or delayed revenue.", "fatal": true}, {"atom": "Source-bounded judgment on QCT margin recovery: dominant Q3 FY26 compression component, whether the gross-margin component can be modelled as reversing with OEM inventory normalisation, and what inventory, supply risk, pricing actions and Q4 FY26 QCT guidance imply", "criterion": "Concludes that the gross-margin (cost-of-revenues) component, the larger fiscal Q3 2026 YoY driver, cannot be modelled as reversing with OEM inventory normalisation alone because management ties it to broad-based industry input-cost increases and to pricing actions that benefit gross margins only gradually; and that rising Qualcomm inventory ($8,379M), the new lost-or-delayed-revenue supply risk, continuing memory-constraint effects on handset OEM demand, and fiscal Q4 2026 QCT guidance of $8.4B-$9.0B bracketing fiscal Q3 QCT revenue of $8,504M do not support a near-term volume rebound beyond management's outlook. Acknowledges the opex ratio remains material.", "fatal": true}], "evidence": [{"source_id": "S1", "quote": "Three Months Ended Nine Months Ended June 28, 2026 June 29, 2025 June 28, 2026 June 29, 2025 QCT: Revenues $ 8,504 $ 8,993", "locator": "", "note": "QCT segment revenues were $8,504 million for the three months ended June 28, 2026 and $8,993 million for the three months ended June 29, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Three%20Months%20Ended", "link_method": "text", "n": 1}, {"source_id": "S1", "quote": "Cost of revenues 4,452 4,497", "locator": "", "note": "QCT segment cost of revenues was $4,452 million (three months ended June 28, 2026) and $4,497 million (three months ended June 29, 2025).", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Cost%20of%20revenues", "link_method": "text", "n": 2}, {"source_id": "S1", "quote": "Operating expenses (R&D and SG&A) 1,860 1,825", "locator": "", "note": "QCT segment operating expenses (R&D and SG&A) were $1,860 million (three months ended June 28, 2026) and $1,825 million (three months ended June 29, 2025).", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Operating%20expenses%20%28R%26D%20and%20SG%26A%29,1%2C825", "link_method": "text", "n": 3}, {"source_id": "S1", "quote": "EBT $ 2,192 $ 2,671", "locator": "", "note": "QCT segment EBT was $2,192 million (three months ended June 28, 2026) and $2,671 million (three months ended June 29, 2025); revenues minus cost of revenues minus operating expenses equals EBT in both periods.", "n": 4}, {"source_id": "S1", "quote": "Consolidated revenues and EBT include the following reconciling items (in millions)", "locator": "", "note": "Unallocated items are reconciling items between reportable-segment EBT and consolidated EBT.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Consolidated%20revenues%20and%20EBT%20include%20the%20following%20reconciling%20items%20%28in%20millions%29", "link_method": "text", "n": 5}, {"source_id": "S1", "quote": "Unallocated cost of revenues ( 97 ) ( 65 )", "locator": "", "note": "Unallocated cost of revenues was $97 million (three months ended June 28, 2026) and $65 million (three months ended June 29, 2025), a reconciling item outside segment EBT.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Unallocated%20cost%20of%20revenues", "link_method": "text", "n": 6}, {"source_id": "S1", "quote": "Unallocated R&D expenses ( 755 ) ( 595 ) ( 2,069 ) ( 1,752 ) Unallocated SG&A expenses ( 323 ) ( 182 )", "locator": "", "note": "Unallocated R&D expenses were $755 million vs $595 million and unallocated SG&A expenses $323 million vs $182 million in the three-month periods, reconciling items outside segment EBT.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Unallocated%20R%26D%20expenses,182", "link_method": "text", "n": 7}, {"source_id": "S1", "quote": "EBT as a % of revenues 26 % 30 % -4 points", "locator": "", "note": "Reported QCT EBT as a percentage of revenues was 26% vs 30%, a change of -4 points (whole-point rounding), three months ended June 28, 2026 vs June 29, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=EBT%20as%20a%20%25%20of%20revenues,%2D4%20points", "link_method": "text", "n": 8}, {"source_id": "S1", "quote": "QCT EBT as a percentage of revenues decreased in the third quarter of fiscal 2026 primarily due to: - lower gross margin, primarily driven by higher product cost, partially offset by higher average selling prices - lower revenues 22 First nine months", "locator": "", "note": "The complete third-quarter attribution list names two items, lower gross margin (higher product cost, partially offset by higher average selling prices) and lower revenues; the list ends before the First nine months heading and contains no operating-expense item.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=QCT%20EBT%20as%20a%20percentage%20of%20revenues%20decreased%20in%20the,First%20nine%20months", "link_method": "text", "n": 9}, {"source_id": "S1", "quote": "average selling prices - lower revenues 22 First nine months", "locator": "", "note": "The third-quarter list ends with lower revenues immediately before the First nine months section.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=average%20selling%20prices,First%20nine%20months", "link_method": "text", "n": 10}, {"source_id": "S1", "quote": "QCT EBT as a percentage of revenues decreased in the first nine months of fiscal 2026 primarily due to: - higher operating expenses", "locator": "", "note": "The first-nine-months attribution list begins with higher operating expenses.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=QCT%20EBT%20as%20a%20percentage%20of%20revenues%20decreased%20in%20the,higher", "link_method": "text", "n": 11}, {"source_id": "S1", "quote": "lower gross margin, primarily driven by higher product cost, partially offset by higher average selling prices", "locator": "", "note": "Lower gross margin is attributed primarily to higher product cost, partially offset by higher average selling prices.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=lower%20gross%20margin%2C%20primarily%20driven%20by%20higher%20product%20cost%2C%20partially,offset%20by%20higher%20average%20selling%20prices", "link_method": "text", "n": 12}, {"source_id": "S1", "quote": "lower handsets revenues, primarily due to lower chipset shipments to certain major OEMs", "locator": "", "note": "Third-quarter QCT handset revenues fell primarily due to lower chipset shipments to certain major OEMs.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=lower%20handsets%20revenues%2C%20primarily%20due%20to%20lower%20chipset%20shipments%20to,certain%20major%20OEMs", "link_method": "text", "n": 13}, {"source_id": "S1", "quote": "customers adjusting build plans to reduce their inventory levels as a result of the negative effects of recent memory supply constraints and related price increases", "locator": "", "note": "Lower shipments were primarily driven by customers adjusting build plans to reduce their inventory levels because of recent memory supply constraints and related price increases.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=customers%20adjusting%20build%20plans%20to%20reduce%20their%20inventory%20levels%20as,supply%20constraints%20and%20related%20price%20increases", "link_method": "text", "n": 14}, {"source_id": "S1", "quote": "Automotive 1,588 984 604", "locator": "", "note": "QCT automotive revenues were $1,588 million vs $984 million, a $604 million increase, in the third quarter.", "n": 15}, {"source_id": "S1", "quote": "$381 million increase in revenues per unit driven by favorable mix and higher average selling prices", "locator": "", "note": "Third-quarter automotive revenues rose by $381 million from revenues per unit, driven by favorable mix and higher average selling prices.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=%24381%20million%20increase%20in%20revenues%20per%20unit%20driven%20by%20favorable,mix%20and%20higher%20average%20selling%20prices", "link_method": "text", "n": 16}, {"source_id": "S1", "quote": "$223 million in higher shipments", "locator": "", "note": "Third-quarter automotive revenues rose by $223 million from higher shipments.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=%24223%20million%20in%20higher%20shipments", "link_method": "text", "n": 17}, {"source_id": "S1", "quote": "higher IoT revenues, primarily due to an increase in revenues per unit primarily driven by favorable mix", "locator": "", "note": "Higher IoT revenues are attributed primarily to higher revenues per unit driven by favorable mix.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=higher%20IoT%20revenues%2C%20primarily%20due%20to%20an%20increase%20in%20revenues,unit%20primarily%20driven%20by%20favorable%20mix", "link_method": "text", "n": 18}, {"source_id": "S1", "quote": "Inventories (in millions) June 28, 2026 September 28, 2025 Raw materials $ 682 $ 336", "locator": "", "note": "Raw materials inventory was $682 million at June 28, 2026 and $336 million at September 28, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Inventories%20%28in%20millions%29,336", "link_method": "text", "n": 19}, {"source_id": "S1", "quote": "Work-in-process 5,005 3,985", "locator": "", "note": "Work-in-process inventory was $5,005 million at June 28, 2026 and $3,985 million at September 28, 2025.", "n": 20}, {"source_id": "S1", "quote": "Finished goods 2,692 2,205 $ 8,379 $ 6,526", "locator": "", "note": "Finished goods were $2,692 million and $2,205 million; total inventories were $8,379 million at June 28, 2026 and $6,526 million at September 28, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=Finished%20goods,6%2C526", "link_method": "text", "n": 21}, {"source_id": "S1", "quote": "negatively impacted our operating cash flows primarily driven by an increase in inventory reflecting certain customer demand impacts", "locator": "", "note": "Operating cash flows for the first nine months of fiscal 2026 were negatively impacted primarily by an increase in inventory reflecting certain customer demand impacts.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=negatively%20impacted%20our%20operating%20cash%20flows%20primarily%20driven%20by%20an,inventory%20reflecting%20certain%20customer%20demand%20impacts", "link_method": "text", "n": 22}, {"source_id": "S1", "quote": "customer demand impacts from memory supply constraints", "locator": "", "note": "The customer demand impacts behind the inventory increase are from memory supply constraints.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=customer%20demand%20impacts%20from%20memory%20supply%20constraints", "link_method": "text", "n": 23}, {"source_id": "S1", "quote": "We expect recent memory supply constraints and related pricing increases to adversely affect demand from several handset OEMs", "locator": "", "note": "In the Q3 FY26 10-Q outlook, Qualcomm expects memory supply constraints and related pricing increases to adversely affect demand from several handset OEMs.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=We%20expect%20recent%20memory%20supply%20constraints%20and%20related%20pricing%20increases,affect%20demand%20from%20several%20handset%20OEMs", "link_method": "text", "n": 24}, {"source_id": "S1", "quote": "The semiconductor industry is experiencing a broad-based increase in input costs and capacity constraints", "locator": "", "note": "The Q3 FY26 10-Q outlook states the semiconductor industry is experiencing a broad-based increase in input costs and capacity constraints.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=The%20semiconductor%20industry%20is%20experiencing%20a%20broad%2Dbased%20increase%20in%20input,costs%20and%20capacity%20constraints", "link_method": "text", "n": 25}, {"source_id": "S1", "quote": "across wafer fabrication, assembly, test, advanced packaging, memory and other materials", "locator": "", "note": "The input-cost and capacity constraints span wafer fabrication, assembly, test, advanced packaging, memory and other materials.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=across%20wafer%20fabrication%2C%20assembly%2C%20test%2C%20advanced%20packaging%2C%20memory%20and%20other%20materials", "link_method": "text", "n": 26}, {"source_id": "S1", "quote": "due in part to increasing demand for leading-edge technologies, AI and data center applications", "locator": "", "note": "The constraints are due in part to increasing demand for leading-edge technologies, AI and data center applications.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=due%20in%20part%20to%20increasing%20demand%20for%20leading%2Dedge%20technologies%2C%20AI,and%20data%20center%20applications", "link_method": "text", "n": 27}, {"source_id": "S1", "quote": "As a result, we continue to see increased product costs from certain of our key suppliers", "locator": "", "note": "As a result, Qualcomm continues to see increased product costs from certain key suppliers.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=As%20a%20result%2C%20we%20continue%20to%20see%20increased%20product%20costs,from%20certain%20of%20our%20key%20suppliers", "link_method": "text", "n": 28}, {"source_id": "S1", "quote": "which could negatively impact our margins", "locator": "", "note": "The increased product costs could negatively impact margins.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=which%20could%20negatively%20impact%20our%20margins", "link_method": "text", "n": 29}, {"source_id": "S1", "quote": "if these supply and capacity constraints limit the availability of components, manufacturing capacity or related services from our suppliers, we may be unable to fully satisfy customer demand", "locator": "", "note": "If supply and capacity constraints limit supplier availability, Qualcomm may be unable to fully satisfy customer demand.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=if%20these%20supply%20and%20capacity%20constraints%20limit%20the%20availability%20of,unable%20to%20fully%20satisfy%20customer%20demand", "link_method": "text", "n": 30}, {"source_id": "S1", "quote": "which could result in lost or delayed revenue", "locator": "", "note": "Unmet customer demand could result in lost or delayed revenue.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=which%20could%20result%20in%20lost%20or%20delayed%20revenue", "link_method": "text", "n": 31}, {"source_id": "S2", "quote": "Three Months Ended Six Months Ended March 29, 2026 March 30, 2025 March 29, 2026 March 30, 2025 QCT: Revenues $ 9,076 $ 9,469", "locator": "", "note": "QCT segment revenues were $9,076 million for the three months ended March 29, 2026 and $9,469 million for the three months ended March 30, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=Three%20Months%20Ended", "link_method": "text", "n": 32}, {"source_id": "S2", "quote": "Cost of revenues 4,700 4,834", "locator": "", "note": "QCT segment cost of revenues was $4,700 million (three months ended March 29, 2026) and $4,834 million (three months ended March 30, 2025).", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=Cost%20of%20revenues", "link_method": "text", "n": 33}, {"source_id": "S2", "quote": "Operating expenses (R&D and SG&A) 1,911 1,778", "locator": "", "note": "QCT segment operating expenses (R&D and SG&A) were $1,911 million (three months ended March 29, 2026) and $1,778 million (three months ended March 30, 2025).", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=Operating%20expenses%20%28R%26D%20and%20SG%26A%29,1%2C778", "link_method": "text", "n": 34}, {"source_id": "S2", "quote": "EBT $ 2,465 $ 2,857", "locator": "", "note": "QCT segment EBT was $2,465 million and $2,857 million in the three months ended March 29, 2026 and March 30, 2025; revenues minus cost of revenues minus operating expenses equals EBT in both periods.", "n": 35}, {"source_id": "S2", "quote": "EBT as a % of revenues 27 % 30 % -3 points", "locator": "", "note": "Reported QCT EBT as a percentage of revenues was 27% vs 30%, a change of -3 points (whole-point rounding), second quarter fiscal 2026 vs 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=EBT%20as%20a%20%25%20of%20revenues,%2D3%20points", "link_method": "text", "n": 36}, {"source_id": "S2", "quote": "QCT EBT as a percentage of revenues decreased in the second quarter of fiscal 2026 primarily due to: - higher operating expenses, primarily driven by higher research and development and selling, general and administrative expenses - lower gross margin, primarily driven by higher product cost, partially offset by higher average selling prices - lower revenues", "locator": "", "note": "The complete second-quarter attribution list names higher operating expenses first, then lower gross margin (higher product cost, partially offset by higher average selling prices), then lower revenues.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=QCT%20EBT%20as%20a%20percentage%20of%20revenues%20decreased%20in%20the,%2D%20lower%20revenues", "link_method": "text", "n": 37}, {"source_id": "S2", "quote": "administrative expenses - lower gross margin, primarily driven by higher product cost", "locator": "", "note": "In the second-quarter list, lower gross margin driven by higher product cost follows the operating-expense item.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=administrative%20expenses", "link_method": "text", "n": 38}, {"source_id": "S2", "quote": "$191 million in higher shipments", "locator": "", "note": "Second-quarter automotive revenues rose by $191 million from higher shipments.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=%24191%20million%20in%20higher%20shipments", "link_method": "text", "n": 39}, {"source_id": "S2", "quote": "$176 million increase in revenues per unit driven by favorable mix and higher average selling prices", "locator": "", "note": "Second-quarter automotive revenues rose by $176 million from revenues per unit, driven by favorable mix and higher average selling prices.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=%24176%20million%20increase%20in%20revenues%20per%20unit%20driven%20by%20favorable,mix%20and%20higher%20average%20selling%20prices", "link_method": "text", "n": 40}, {"source_id": "S2", "quote": "Inventories (in millions) March 29, 2026 September 28, 2025 Raw materials $ 580 $ 336", "locator": "", "note": "Raw materials inventory was $580 million at March 29, 2026 and $336 million at September 28, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=Inventories%20%28in%20millions%29,336", "link_method": "text", "n": 41}, {"source_id": "S2", "quote": "Work-in-process 4,346 3,985", "locator": "", "note": "Work-in-process inventory was $4,346 million at March 29, 2026 and $3,985 million at September 28, 2025.", "n": 42}, {"source_id": "S2", "quote": "Finished goods 2,442 2,205 $ 7,368 $ 6,526", "locator": "", "note": "Total inventories were $7,368 million at March 29, 2026 and $6,526 million at September 28, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=Finished%20goods,6%2C526", "link_method": "text", "n": 43}, {"source_id": "S2", "quote": "As we look forward to the next several quarters:", "locator": "", "note": "Heading of the Q2 FY26 10-Q forward-looking outlook list.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=As%20we%20look%20forward%20to%20the%20next%20several%20quarters", "link_method": "text", "n": 44}, {"source_id": "S2", "quote": "We expect leading process technology nodes to continue to drive product cost increases", "locator": "", "note": "The Q2 FY26 10-Q outlook expects leading process technology nodes to continue to drive product cost increases.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=We%20expect%20leading%20process%20technology%20nodes%20to%20continue%20to%20drive,product%20cost%20increases", "link_method": "text", "n": 45}, {"source_id": "S2", "quote": "from certain of our key semiconductor wafer suppliers", "locator": "", "note": "The node-driven product cost increases come from certain key semiconductor wafer suppliers.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm#:~:text=from%20certain%20of%20our%20key%20semiconductor%20wafer%20suppliers", "link_method": "text", "n": 46}, {"source_id": "S3", "quote": "Qualcomm Incorporated (NASDAQ: QCOM) today announced results for its fiscal third quarter ended June 28, 2026", "locator": "", "note": "Qualcomm Incorporated (NASDAQ: QCOM) announced results for its fiscal third quarter ended June 28, 2026.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=Qualcomm%20Incorporated%20%28NASDAQ%3A%20QCOM%29%20today%20announced%20results%20for%20its%20fiscal,third%20quarter%20ended%20June%2028%2C%202026", "link_method": "text", "n": 47}, {"source_id": "S3", "quote": "EBT as % of revenues 26% 30% -4 points", "locator": "", "note": "The earnings release reports QCT EBT as a percentage of revenues of 26% vs 30%, -4 points, matching the 10-Q.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=EBT%20as%20%25%20of%20revenues,%2D4%20points", "link_method": "text", "n": 48}, {"source_id": "S3", "quote": "The semiconductor industry is experiencing a broad-based increase in input costs, across wafer fabrication, assembly, test, advanced packaging, memory and other materials.", "locator": "", "note": "The Q3 FY26 earnings release repeats that the semiconductor industry is experiencing a broad-based increase in input costs across wafer fabrication, assembly, test, advanced packaging, memory and other materials.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=The%20semiconductor%20industry%20is%20experiencing%20a%20broad%2Dbased%20increase%20in%20input,advanced%20packaging%2C%20memory%20and%20other%20materials", "link_method": "text", "n": 49}, {"source_id": "S3", "quote": "We are taking concrete actions to reflect the higher input costs in our product pricing", "locator": "", "note": "Qualcomm is taking actions to reflect the higher input costs in its product pricing.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=We%20are%20taking%20concrete%20actions%20to%20reflect%20the%20higher%20input,costs%20in%20our%20product%20pricing", "link_method": "text", "n": 50}, {"source_id": "S3", "quote": "expect these actions to benefit our gross margins over time", "locator": "", "note": "Qualcomm expects the pricing actions to benefit gross margins over time.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=expect%20these%20actions%20to%20benefit%20our%20gross%20margins%20over%20time", "link_method": "text", "n": 51}, {"source_id": "S3", "quote": "as the pricing changes gradually come into effect", "locator": "", "note": "The benefit arrives as the pricing changes gradually come into effect.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=as%20the%20pricing%20changes%20gradually%20come%20into%20effect", "link_method": "text", "n": 52}, {"source_id": "S3", "quote": "These factors are reflected in both our fiscal 2026 third quarter performance and fourth quarter guidance.", "locator": "", "note": "The input-cost and pricing factors are reflected in fiscal 2026 third-quarter performance and fourth-quarter guidance.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=These%20factors%20are%20reflected%20in%20both%20our%20fiscal%202026%20third,quarter%20performance%20and%20fourth%20quarter%20guidance", "link_method": "text", "n": 53}, {"source_id": "S3", "quote": "Current Guidance Q4 FY26 Estimates 1 Revenues $9.7B - $10.5B Supplemental Revenue Information QCT revenues $8.4B - $9.0B", "locator": "", "note": "Q4 FY26 guidance: total revenues $9.7B-$10.5B, QCT revenues $8.4B-$9.0B.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm#:~:text=Current%20Guidance,%248.4B%20%2D%20%249.0B", "link_method": "text", "n": 54}, {"source_id": "S1", "quote": "As we look forward to the next several quarters:", "locator": "", "note": "Heading of the Q3 FY26 10-Q forward-looking outlook list.", "link": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm#:~:text=As%20we%20look%20forward%20to%20the%20next%20several%20quarters", "link_method": "text", "n": 55}], "sources": [{"id": "S1", "title": "Qualcomm — Form 10-Q, quarter ended June 28, 2026", "url": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000086/qcom-20260628.htm", "doc_type": "10-Q", "date": "2026-07-29"}, {"id": "S2", "title": "Qualcomm — Form 10-Q, quarter ended March 29, 2026", "url": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/qcom-20260329.htm", "index_url": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000061/0000804328-26-000061-index.html", "doc_type": "10-Q", "date": "2026-04-29"}, {"id": "S3", "title": "Qualcomm — Fiscal 2026 third-quarter earnings release, July 29, 2026", "url": "https://www.sec.gov/Archives/edgar/data/804328/000080432826000085/qcom062826erex991.htm", "doc_type": "EX-99.1", "date": "2026-07-29"}], "has_trajectories": true, "reference_note": null, "frozen_sha256": "371337e78ff88152a3bb5cdb78d8abf4b718c45c8686858a45021bba99849eb4", "review_scope": "The question, reference analysis and scoring criteria used for this evaluation.", "lineage": {"stages": [{"key": "discovery", "label": "Discovery", "status": "passed", "note": "1 documented step.", "events": [{"date": "2026-10-03T07:56:15.441962Z", "title": "Task proposed to test an analytical limitation", "detail": "The proposal identified 10 candidate relationships from 3 sources.", "kind": "ok"}]}, {"key": "novelty_check", "label": "Novelty check", "status": "passed", "note": "1 documented step.", "events": [{"date": "2026-10-03T07:56:15.441962Z", "title": "Compared with existing and proposed tasks", "detail": "The candidate was compared with existing and proposed tasks and continued to the next stage.", "kind": "ok"}]}, {"key": "integration", "label": "Integration", "status": "passed", "note": "3 documented steps.", "events": [{"date": "2026-10-03T07:56:15.441962Z", "title": "243 statements classified as reported fact or inference", "detail": "", "kind": "ok"}, {"date": "2026-10-03T07:56:15.441962Z", "title": "Supporting passages located in 3 sources", "detail": "The supporting passages were located in the source documents.", "kind": "ok"}, {"date": "2026-10-03T07:56:15.441962Z", "title": "Analysis linked: 9 relationships, 13 answer components, 51 supporting passages", "detail": "Attribute Qualcomm QCT segment EBT-margin compression in fiscal Q2 and Q3 2026 (year over year and Q2-to-Q3 sequential) between the segment cost-of-revenues ratio and the R&D+SG&A operating-expense ratio. Test management's changing attribution against the line items. Then use the change in the product-cost outlook disclosure between the Q2 and Q3 FY26 10-Qs, together with the inventory build, the automotive price/volume split, the pricing-action statement and Q4 FY26 QCT guidance, to bound whether margin recovery can be modelled as reversing with OEM inventory normalisation.", "kind": "ok"}]}, {"key": "difficulty", "label": "Difficulty screen", "status": "returned", "note": "Revised once after comparison with other proposed tasks, then reassessed and selected.", "events": [{"date": null, "title": "Initial difficulty assessment", "kind": "ok", "detail": "Estimated difficulty: highest band. Reasoning depth: 4/4; Reconciliation across sources: 4/4; Entity and population definitions: 3/4; Periods and document versions: 3/4; Conditional reasoning: 2/4; Professional judgment: 4/4; Changes in financial or regulatory state: 2/4; Verification of resulting outcomes: 2/4."}, {"date": null, "title": "Selected for revision after comparison with other proposed tasks", "kind": "edit", "detail": "The task was revised to add a further analysis supported by the sources, then assessed again."}, {"date": null, "title": "Compare changes in the product-cost outlook", "kind": "edit", "detail": "Added a comparison of Qualcomm’s Q2 and Q3 outlooks, from leading-node wafer costs to broader input-cost inflation and capacity constraints. This tests whether handset-inventory normalization alone can explain a potential margin recovery, and recognizes that supply constraints can also restrict revenue. The earlier leading-node explanation remains in the risk factors, so the change is a broader outlook rather than a withdrawal of that driver."}, {"date": null, "title": "Reassessment of the revised version", "detail": "Estimated difficulty: highest band. Reasoning depth: 4/4; Reconciliation across sources: 4/4; Entity and population definitions: 3/4; Periods and document versions: 4/4; Conditional reasoning: 3/4; Professional judgment: 4/4; Changes in financial or regulatory state: 2/4; Verification of resulting outcomes: 2/4.", "kind": "ok"}, {"date": null, "title": "Assessment rationale (excerpt)", "detail": "The revised task adds a comparison across reporting dates: the Q2 FY26 10-Q product-cost outlook (leading-node wafer cost) must be reconciled with the Q3 FY26 10-Q and Q3 earnings-release outlook (broad-based input-cost and capacity constraints). The central work is a multi-step attribution: compute QCT cost-of-revenues and operating-expense ratios from the Q2/Q3 FY26 segment tables, compare year-over-year and sequential movements, tie them to the reported EBT-margin changes, and test management's changing attribution against the line items.", "kind": "ok"}, {"date": null, "title": "Selected after reassessment", "detail": "This version was selected for evidence collection and reference-answer development.", "kind": "ok"}], "assessment": {"mode": "structural_estimate_without_solving", "predicted_band": "frontier", "dimensions": {"relation_depth": 4, "cross_source_reconciliation": 4, "identity_or_population": 3, "temporal_or_version": 4, "conditional_branching": 3, "professional_judgment": 4, "state_transition": 2, "post_action_verification": 2}, "shortcut_available": false, "material_ambiguity": false, "batch_rank": 7, "cohort_size": 16, "decision": "selected", "previous_versions": [{"predicted_band": "frontier", "dimensions": {"relation_depth": 4, "cross_source_reconciliation": 4, "identity_or_population": 3, "temporal_or_version": 3, "conditional_branching": 2, "professional_judgment": 4, "state_transition": 2, "post_action_verification": 2}, "batch_rank": 12, "cohort_size": 16, "decision": "revision_required", "change_title": "Compare changes in the product-cost outlook", "change_summary": "Added a comparison of Qualcomm’s Q2 and Q3 outlooks, from leading-node wafer costs to broader input-cost inflation and capacity constraints. This tests whether handset-inventory normalization alone can explain a potential margin recovery, and recognizes that supply constraints can also restrict revenue. The earlier leading-node explanation remains in the risk factors, so the change is a broader outlook rather than a withdrawal of that driver."}]}}, {"key": "evidence", "label": "Reference analysis", "status": "passed", "note": "16 documented steps.", "events": [{"date": "2026-10-03T08:06:13.381504Z", "title": "Reference analysis written", "detail": "QCT segment EBT-margin compression is opex-led in Q2 FY26 YoY (opex ratio +2.28 pp vs cost ratio +0.73 pp) and cost-led in Q3 FY26 YoY (cost ratio +2.35 pp vs opex ratio +1.58 pp; computed -3.92 pp vs reported -4 points), with both ratios worsening sequentially and opex narrowly larger (+0.82 vs +0.57 pp) as revenue fell $572M while opex fell only $51M. Management's attribution lists are directionally consistent, but the Q3 quarter list omits the still-rising opex ratio. Between the Q2 and Q3 10-Q outlooks the product-cost driver shifts from leading-node wafer-supplier cost to a broad-based industry input-cost and capacity increase (in part AI/data-center demand), with a new lost-or-delayed-revenue supply risk. Management's remedy is pricing actions that benefit gross margins only gradually, so the gross-margin component cannot be modelled as reversing with OEM inventory normalisation alone. Qualcomm's inventory rose $1,853M to $8,379M and Q4 FY26 QCT guidance of $8.4B-$9.0B brackets the Q3 level, so the evidence does not support a near-term volume rebound beyond management's stated outlook.", "kind": "ok"}, {"date": "2026-10-03T08:06:13.381504Z", "title": "Evidence assembled: 53 verbatim quotations", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:06:13.381504Z", "title": "Analysis objective defined", "detail": "Attribute Qualcomm QCT segment EBT-margin compression in fiscal Q2 and Q3 2026 (year over year and Q2-to-Q3 sequential) between the segment cost-of-revenues ratio and the R&D+SG&A operating-expense ratio. Test management's changing attribution against the line items. Then use the change in the product-cost outlook disclosure between the Q2 and Q3 FY26 10-Qs, together with the inventory build, the automotive price/volume split, the pricing-action statement and Q4 FY26 QCT guidance, to bound whether margin recovery can be modelled as reversing with OEM inventory normalisation.", "kind": "ok"}, {"date": "2026-10-03T08:06:13.381504Z", "title": "Reference calculation recorded in 19 steps", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:06:13.381504Z", "title": "Definitions and scope checked: supported", "detail": "Compatible on entity, period, unit, scope, population.", "kind": "ok"}, {"date": "2026-10-03T08:06:13.381504Z", "title": "Professional interpretation checked: supported", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:10:25.366715Z", "title": "Quoted passages checked against sources", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:10:25.529724Z", "title": "Evidence review completed", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:45:41.403508Z", "title": "Reference analysis written", "detail": "QCT segment EBT-margin compression is opex-led in Q2 FY26 YoY (opex ratio +2.28 pp vs cost ratio +0.73 pp) and cost-led in Q3 FY26 YoY (cost ratio +2.35 pp vs opex ratio +1.58 pp; computed -3.92 pp vs reported -4 points), with both ratios worsening sequentially and opex narrowly larger (+0.82 vs +0.57 pp) as revenue fell $572M while opex fell only $51M. Management's Q2 FY26 attribution list is consistent with the line items (higher operating expenses, lower gross margin, lower revenues); the Q3 FY26 list is only partially consistent: its two items (lower gross margin, lower revenues) match, but it omits the operating-expense item although the segment opex ratio rose +1.58 pp YoY. The nine-month list is not scored. Between the Q2 and Q3 10-Q outlooks the product-cost driver shifts from leading-node wafer-supplier cost to a broad-based industry input-cost and capacity increase (in part AI/data-center demand), with a new lost-or-delayed-revenue supply risk. Management's remedy is pricing actions that benefit gross margins only gradually, so the gross-margin component cannot be modelled as reversing with OEM inventory normalisation alone. Qualcomm's inventory rose $1,853M to $8,379M and Q4 FY26 QCT guidance of $8.4B-$9.0B brackets the Q3 level, so the evidence does not support a near-term volume rebound beyond management's stated outlook.", "kind": "ok"}, {"date": "2026-10-03T08:45:41.403508Z", "title": "Analysis objective defined", "detail": "Attribute Qualcomm QCT segment EBT-margin compression in fiscal Q2 and Q3 2026 (year over year and Q2-to-Q3 sequential) between the segment cost-of-revenues ratio and the R&D+SG&A operating-expense ratio. Test management's changing attribution against the line items. Then use the change in the product-cost outlook disclosure between the Q2 and Q3 FY26 10-Qs, together with the inventory build, the automotive price/volume split, the pricing-action statement and Q4 FY26 QCT guidance, to bound whether margin recovery can be modelled as reversing with OEM inventory normalisation.", "kind": "ok"}, {"date": "2026-10-03T08:45:41.403508Z", "title": "Evidence assembled: 55 verbatim quotations", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:45:41.403508Z", "title": "Reference calculation recorded in 21 steps", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:45:41.403508Z", "title": "Professional interpretation checked: supported", "detail": "", "kind": "ok"}, {"date": "2026-10-03T08:45:41.403508Z", "title": "Definitions and scope checked: supported", "detail": "Compatible on entity, period, unit, scope, population.", "kind": "ok"}, {"date": "2026-10-03T09:03:51.708453Z", "title": "Quoted passages checked against sources", "detail": "", "kind": "ok"}, {"date": "2026-10-03T09:03:51.857228Z", "title": "Evidence review completed", "detail": "", "kind": "ok"}]}, {"key": "reproduction", "label": "Independent reproduction", "status": "passed", "note": "4 documented steps.", "events": [{"date": "2026-10-03T08:19:56.761881Z", "title": "Independent-review materials checked", "detail": "The independent reviewer received the objective, supporting quotations and descriptions of the required outputs, without the reference answer.", "kind": "ok"}, {"date": "2026-10-03T08:19:56.815902Z", "title": "Independent reproduction: reproduced (13 answer components)", "detail": "", "kind": "ok"}, {"date": "2026-10-03T09:58:52.878974Z", "title": "Independent-review materials checked", "detail": "The independent reviewer received the objective, supporting quotations and descriptions of the required outputs, without the reference answer.", "kind": "ok"}, {"date": "2026-10-03T09:58:52.934269Z", "title": "Independent reproduction: reproduced (13 answer components)", "detail": "", "kind": "ok"}]}, {"key": "comparison", "label": "Comparison", "status": "returned", "note": "2 issues identified during review.", "events": [{"date": "2026-10-03T08:32:29.630454Z", "title": "Answer-by-answer comparison: revision required", "detail": "The numerical calculations matched. The task and reference answer differed on whether management attribution should be judged separately for each period, and the necessary nine-month segment details were absent from the supplied evidence. The independent reproduction also inferred cost pressure from inventory growth without support. Both the task requirements and the reproduction required revision.", "kind": "issue"}, {"date": "2026-10-03T08:32:29.630454Z", "title": "Source check: shared assumptions supported", "detail": "The reviewer checked the cited source passages and independently verified the entity, periods, units, sources, calculations and limits of the conclusions. The two differences affected only one answer each; neither was an error shared by both answers.", "kind": "ok"}, {"date": "2026-10-03T08:33:11.438089Z", "title": "Defect found: reference analysis or reasoning", "detail": "The reference answer was returned for correction.", "kind": "issue"}, {"date": "2026-10-03T11:39:14.344670Z", "title": "Answer-by-answer comparison: equivalent", "detail": "All 13 reference answer components reproduced. Six numeric ratio answer components, the component ranking and the segment-scope answer component match exactly; auto per-unit share (63.1) and inventory build ($1,853M) match exactly in value. Eight nonmaterial differences (Q3 label wording covered by an existing accepted alternative, ordering-based reasoning, nine-month commentary, Q2 automotive sum, omitted caveats, inventory surplus, guidance framing) are preserved and accepted as equivalent after checking against cited source passages. Independent recomputation from cited source passages confirms all shared premises.", "kind": "ok"}]}, {"key": "family", "label": "Problem family", "status": "passed", "note": "1 documented step.", "events": [{"date": "2026-10-03T12:05:42.877464Z", "title": "Problem family accepted", "detail": "The verified analysis was accepted within the proposed task type.", "kind": "ok"}]}, {"key": "question", "label": "Question & scoring criteria", "status": "passed", "note": "19 documented steps.", "events": [{"date": "2026-10-03T12:21:35.788091Z", "title": "Scoring criteria checked: 12 scored items, 7 automatic-failure rules", "detail": "", "kind": "ok"}, {"date": "2026-10-03T12:21:35.788111Z", "title": "Question and scoring criteria prepared", "detail": "The task asks whether Qualcomm QCT's FY2026 margin compression and its recovery path are driven by product cost or operating expense, and whether management's per-period attribution is consistent with the segment line items. The visible question defines the two ratios, the three comparison windows, the per-period attribution scope (nine-month list is context only), the segment-versus-consolidated distinction, and the rounding conventions. It does not list the hidden component values, the dominance outcome per window, the attribution labels, the inventory figures, or the outlook wording change. The automotive price/volume split is not scored.", "kind": "ok"}, {"date": "2026-10-03T12:23:08.432400Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T12:24:38.634598Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T12:25:19.931968Z", "title": "Question finalized for evaluation", "detail": "", "kind": "ok"}, {"date": "2026-10-03T13:22:23.543330Z", "title": "Scoring criteria checked: 12 scored items, 8 automatic-failure rules", "detail": "", "kind": "ok"}, {"date": "2026-10-03T13:22:23.543349Z", "title": "Question and scoring criteria prepared", "detail": "The task asks what drives Qualcomm QCT's FY2026 EBT-margin compression, whether management's per-period attribution matches the segment line items, and whether margin recovery can be modelled as reversing with OEM inventory normalisation. The visible question now explicitly asks for Qualcomm's own inventory balances at the three specified dates with the change in USD millions and percent, and for the change in the outlook description of product-cost drivers and related supply risk to revenue between the Q2 and Q3 FY26 10-Qs, so every automatic-failure criterion is visibly requested. The former 'product cost or operating expense' option phrasing was replaced by 'identify which component is larger in each comparison' so no option set containing an expected answer is listed. No hidden values, directions, attribution labels or risk wording are revealed. The automotive price/volume split is not scored. Seven required output components.", "kind": "ok"}, {"date": "2026-10-03T13:24:33.474676Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified. Revision note: Inventory balances and supply-risk disclosure change now requested visibly; reference answer unchanged.", "kind": "ok"}, {"date": "2026-10-03T13:26:28.625143Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified. Revision note: Inventory balances and supply-risk disclosure change now requested visibly; reference answer unchanged.", "kind": "ok"}, {"date": "2026-10-03T13:28:43.971655Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified. Revision note: Inventory balances and supply-risk disclosure change now requested visibly; reference answer unchanged.", "kind": "ok"}, {"date": "2026-10-03T13:31:18.612962Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified. Revision note: Inventory balances and supply-risk disclosure change now requested visibly; reference answer unchanged.", "kind": "ok"}, {"date": "2026-10-03T13:43:24.225235Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified. Revision note: Inventory balances and supply-risk disclosure change now requested visibly; reference answer unchanged.", "kind": "ok"}, {"date": "2026-10-03T13:44:07.202131Z", "title": "Question finalized for evaluation", "detail": "", "kind": "ok"}, {"date": "2026-10-03T17:29:19.663769Z", "title": "Scoring criteria checked: 12 scored items, 10 automatic-failure rules", "detail": "", "kind": "ok"}, {"date": "2026-10-03T17:29:19.663794Z", "title": "Question and scoring criteria prepared", "detail": "Only the management-attribution request changed: the opening clause now asks how management's attribution compares with the segment line items, and the per-period request now defines a determinate completeness test (does the stated attribution name every QCT line item whose ratio to QCT revenues moved adversely year over year, or omit any such item), asks for any omitted item, and asks which named items match the segment line items. This removes the primary-cause versus complete-enumeration ambiguity, so the unchanged reference answer label (Q2 complete/consistent; All other wording and the first revision’s additions (inventory balances, outlook disclosure change, no listed option sets for the larger component) are retained. One research question with one decisive judgment (recovery character); seven deliverable components plus scope and precision instructions, each tested. The automotive price/volume split is not scored.", "kind": "ok"}, {"date": "2026-10-03T17:30:15.565109Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified. Revision note: Attribution request now asks for complete enumeration of adversely moving line items; reference answer unchanged.", "kind": "ok"}, {"date": "2026-10-03T17:31:21.988205Z", "title": "Question finalized for evaluation", "detail": "", "kind": "ok"}, {"date": "2026-10-03T19:01:23.359925Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:02:12.125156Z", "title": "Question finalized for evaluation", "detail": "", "kind": "ok"}]}, {"key": "validity", "label": "Validity review", "status": "passed", "note": "2 documented steps.", "events": [{"date": "2026-10-03T17:02:07.719709Z", "title": "Validity review: valid", "detail": "", "kind": "ok"}, {"date": "2026-10-03T18:38:38.761739Z", "title": "Validity review: valid", "detail": "", "kind": "ok"}]}, {"key": "consistency", "label": "Consistency review", "status": "returned", "note": "4 issues identified during review.", "events": [{"date": "2026-10-03T12:44:38.612266Z", "title": "Defect found: question or scoring criteria", "detail": "The question and grading criteria were returned for revision.", "kind": "issue"}, {"date": "2026-10-03T17:10:22.976639Z", "title": "Question–reference consistency: inconsistent", "detail": "The grading rule rejected a reasonable reading of management’s explanation. Lower revenue explained about 1.17 of the 1.58 percentage-point increase in the operating-expense ratio, while higher expense explained about 0.41 point; management had described only the primary causes.", "kind": "issue"}, {"date": "2026-10-03T17:11:01.523280Z", "title": "Review decision: revision required", "detail": "The grading rule rejected a reasonable reading of management’s explanation. Lower revenue explained about 1.17 of the 1.58 percentage-point increase in the operating-expense ratio, while higher expense explained about 0.41 point; management had described only the primary causes.", "kind": "issue"}, {"date": "2026-10-03T17:12:17.154701Z", "title": "Defect found: question or scoring criteria", "detail": "The question and grading criteria were returned for revision.", "kind": "issue"}, {"date": "2026-10-03T18:46:22.120268Z", "title": "Question–reference consistency: consistent", "detail": "", "kind": "ok"}, {"date": "2026-10-03T18:46:26.316403Z", "title": "Review decision: passed", "detail": "", "kind": "ok"}, {"date": "2026-10-03T19:02:19.919648Z", "title": "Review decision: passed", "detail": "", "kind": "ok"}]}, {"key": "polish", "label": "Polish", "status": "edited", "note": "1 wording revision.", "events": [{"date": "2026-10-03T19:00:40.248299Z", "title": "Polish review 1: revision requested", "detail": "", "kind": "edit"}, {"date": "2026-10-03T19:04:51.625972Z", "title": "Polish review 2: passed", "detail": "", "kind": "ok"}]}, {"key": "acceptance", "label": "Acceptance", "status": "passed", "note": "Accepted.", "events": []}]}};
